INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (1, 'What is RERA Gujarat, and why is it important?', 'RERA (Real Estate Regulatory Authority) Gujarat protects home buyers by ensuring timely project delivery, transparency, and standard pricing rules. Always check the RERA registration number of a project before buying.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T03:23:03.440Z', '2026-07-27T03:23:03.440Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (2, 'Is it a good time to buy property in {{city}}?', 'Yes, {{city}} is experiencing high infrastructure growth with the expansion of highways, metro connectivity, and corporate hubs, making it an excellent long-term real estate investment.', 'CITY_PAGE', 1, NULL, NULL, '2026-07-27T03:23:03.696Z', '2026-07-27T03:23:03.696Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (3, 'What are the average property rates in {{locality}}?', 'Property rates in {{locality}} range widely depending on the project type, builder brand, and ready-to-move status. Standard flats range from ₹5,000 to ₹12,000 per sq. ft.', 'LOCALITY_PAGE', NULL, 4, NULL, '2026-07-27T03:23:03.949Z', '2026-07-27T03:23:03.949Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (4, 'Can I find a verified {{bhk}} {{propertyType}} in {{locality}} under {{budget}}?', 'Yes! There are several projects in {{locality}} that offer {{bhk}} {{propertyTypePlural}} within {{budget}}. Always verify developer RERA certifications and NA plot documentation.', 'LONG_TAIL', NULL, 1, 1, '2026-07-27T03:23:04.202Z', '2026-07-27T03:23:04.202Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (5, 'Why is real estate in Gujarat considered a good investment?', 'Gujarat has strong economic growth, expanding infrastructure, industrial development, GIDC zones, metro connectivity, and growing commercial hubs, making it an attractive market for residential, commercial, and industrial real estate investment.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T04:45:56.031Z', '2026-07-27T04:45:56.031Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (6, 'Which cities have the best real estate opportunities in Gujarat?', 'Ahmedabad, Surat, Vadodara, Rajkot, Gandhinagar, and GIFT City are among the major real estate markets in Gujarat, each offering different residential, commercial, and industrial investment opportunities.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T04:45:56.293Z', '2026-07-27T04:45:56.293Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (7, 'What should I check before buying property in Gujarat?', 'Buyers should verify property title documents, 7/12 land records, NA permission where applicable, RERA registration, approved building plans, encumbrance details, and applicable stamp duty and registration requirements.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T04:45:56.550Z', '2026-07-27T04:45:56.550Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (8, 'What types of properties are available in Gujarat?', 'Buyers can find apartments, flats, villas, independent houses, residential plots, commercial offices, shops, industrial land, GIDC sheds, agricultural land, and other real estate opportunities across Gujarat.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T04:45:56.805Z', '2026-07-27T04:45:56.805Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (9, 'Is RERA registration important when buying property in Gujarat?', 'Yes. RERA registration helps buyers verify project information, builder details, approved plans, project timelines, and other important disclosures before making a property purchase.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T04:45:57.061Z', '2026-07-27T04:45:57.061Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, city_id, locality_id, property_type_id, created_at, updated_at) VALUES (10, 'What is the best city for real estate investment in Gujarat?', 'Ahmedabad, Surat, Vadodara, Gandhinagar, and GIFT City are among the top real estate investment destinations in Gujarat.', 'HOMEPAGE', NULL, NULL, NULL, '2026-07-27T04:53:56.137Z', '2026-07-27T04:53:56.137Z') ON CONFLICT DO NOTHING;
